\begin{proposition}[Semidirect Products Are Lie Groups]
\label{exer:7-31}




\dcref{ch7:7.31}
The multiplication in Definition~\ref{def:7-51-extra-1} defines a Lie group
with identity $(e,e)$ and inverse
$(n,h)^{-1}=(\theta_{h^{-1}}(n^{-1}),h^{-1})$.
\end{proposition}

